package com.mendes.scheduling_platform.tenant; import com.mendes.scheduling_platform.security.TenantContext; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/tenants") public class TenantController { private final TenantService service; private final TenantRepository repo; public TenantController(TenantService s,TenantRepository r){service=s;repo=r;} public record Register(@NotBlank String name,@NotBlank @Pattern(regexp="[a-z0-9-]+") String slug,@NotBlank String ownerName,@Email @NotBlank String email,@Size(min=8) String password,String phone,String address){} @PostMapping("/register") public Tenant register(@Valid @RequestBody Register r){return service.register(new TenantService.Registration(r.name(),r.slug(),r.ownerName(),r.email(),r.password(),r.phone(),r.address()));} @GetMapping("/me") Tenant me(){return repo.findById(TenantContext.getRequired()).orElseThrow();} @PutMapping("/me") Tenant update(@RequestBody Tenant in){Tenant t=me(); t.setName(in.getName());t.setLogoUrl(in.getLogoUrl());t.setCoverUrl(in.getCoverUrl());t.setPrimaryColor(in.getPrimaryColor());t.setPhone(in.getPhone());t.setInstagram(in.getInstagram());t.setAddress(in.getAddress());return repo.save(t);} }
